+        await expect(new PaymentRefundService(fake.value).settleRefund(refund.id))
+            .resolves.toEqual({ status: 'SUCCEEDED', wasSubmitted: true });
+        expect(fake.createRefund).toHaveBeenCalledTimes(1);
